import itertools

def find_sets(n):
    target = n**2 - 1
    solutions = []

    # x_i are in {0, ..., target}
    # y_j are in {0, ..., target}
    # X = {x_0, ..., x_{n-1}}, Y = {y_0, ..., y_{n-1}}
    # x_0 = 0, y_0 = 0
    # x_{n-1} + y_{n-1} = target

    # Let's iterate over all possible sets X of size n containing 0.
    # To limit the search, we use the property that X+Y = {0, ..., target}.
    # This means x_1, x_2, ..., x_{n-1} and y_1, y_2, ..., y_{n-1} 
    # must be such that {x_i} \cup {y_j} contains {1, 2, ..., n-1}.
    # Also x_i < n^2.

    # This is still too many. Let's use the property that 
    # if X+Y = {0, ..., n^2-1}, then X and Y must be "dense".
    # Let's try all X such that x_i are in {0, ..., target}.
    # Actually, there's a very limited number of such sets.

    # For n=3, target=8, X = {0, x1, x2}, Y = {0, y1, y2}
    # x2+y2 = 8, x1 < x2, y1 < y2.
    # X+Y = {0, x1, x2, y1, y2, x1+y1, x1+y2, x2+y1, x2+y2} = {0, ..., 8}

    # Let's just brute force n=3 and n=4.
    for x1 in range(1, target + 1):
        for x2 in range(x1 + 1, target + 1):
            X = [0, x1, x2]
            for y1 in range(1, target + 1):
                for y2 in range(y1 + 1, target + 1):
                    Y = [0, y1, y2]
                    if x2 + y2 == target:
                        sums = set()
                        for x in X:
                            for y in Y:
                                sums.add(x + y)
                        if len(sums) == 9 and max(sums) == 8 and min(sums) == 0:
                            solutions.append((tuple(sorted(X)), tuple(sorted(Y))))
    return solutions

n3_sol = find_sets(3)
print(f"n=3: {n3_sol}")

